#!/bin/bash
#  #501 pcc2defaultkill KILL TABLE 4 -- the pass-3 repair (46 rows), twenty-two mutants.  The ten pass-3 mutants are
#  scored by BOTH instruments: the 36-row one frozen in killtable3_20260905/ (md5 10737375) must stay 36/36 on them --
#  the measured breach -- and the 46-row one must red them (M_RELOAD is the DISCLOSED exception: 46/46 expected).
#  BASE owes 46/46 AND 36/36.
set -u
G=/mnt/c/DocumentNoSnc/CC/GXEMUL; SEC=$G/GXEMUL-SEC; F=src/devices/dev_pcc2.c; T=/tmp/gxdk501c
OUT=/tmp/killdk501c; PROBE=pcc2_default_probe.py
OLDK=$SEC/regress/artifacts/pcc2defaultkill/killtable3_20260905
say() { echo "[$(date +%H:%M:%S)] $*"; }
die() { echo "*** ABORT: $*"; exit 9; }
rm -rf "$T" "$OUT"; mkdir -p "$OUT/old36"
cp -a "$G/build" "$T" || die "clone failed"
cmp -s "$T/$F" "$SEC/$F" || { cp "$SEC/$F" "$T/$F"; say "  clone's $F refreshed from SEC (BASE rebuilds it)"; }
grep -q "end-span path" "$T/$F" || die "the clone's $F lacks the pass-3 comment"
cp "$SEC/regress/$PROBE" "$OUT/frozen_probe.py" || die "cannot freeze probe"
cp "$SEC/regress/pcc2_width_probe.py" "$OUT/pcc2_width_probe.py" || die "cannot freeze the session helper source"
cp "$OLDK/frozen_probe.py" "$OUT/old36/frozen_probe.py" || die "cannot copy the pass-3 instrument"
cp "$OLDK/pcc2_width_probe.py" "$OUT/old36/pcc2_width_probe.py" || die "cannot copy the pass-3 helper"
[ "$(md5sum "$OUT/old36/frozen_probe.py" | cut -c1-8)" = "10737375" ] || die "the pass-3 instrument is not 10737375"
[ "$(grep -c '^row(' "$OUT/frozen_probe.py")" = 46 ] || die "the live probe is not the 46-row instrument"
say "  instruments frozen: new $(md5sum "$OUT/frozen_probe.py" | cut -c1-8) (46 rows)  old36 10737375"
build() { cd "$T" || die cd; rm -f src/devices/dev_pcc2.o; make -j4 > "$OUT/build_$1.log" 2>&1; [ "$T/gxemul" -nt "$T/$F" ] || die "$1: binary not newer than source"; }
score() {   # name expect instrument-dir tag
    cd "$SEC/regress" || die cd
    python3 -u "$3/frozen_probe.py" "$T/gxemul" "$1" > "$OUT/$1$4.out" 2>&1
    grep -q PCC2D_PROBE_DONE "$OUT/$1$4.out" || die "$1$4: NO COMPLETION SENTINEL"
    say "  $1$4 [$2]: $(grep -m1 PCC2D_RESULT "$OUT/$1$4.out")"
    grep -m1 PCC2D_RED "$OUT/$1$4.out" | sed 's/PCC2D_RED=/      RED: /' || true
}
mut() {   # name expect body both|new
    echo "$F  mutant $1" > "$T/.MUTANT"; cp "$SEC/$F" "$T/$F"
    python3 - "$T/$F" "$3" <<'PYEOF'
import io, sys
p, body = sys.argv[1], sys.argv[2]; s = io.open(p, encoding='utf-8').read()
ns = {'s': s}; exec(body, ns); io.open(p, 'w', encoding='utf-8', newline='\n').write(ns['s'])
PYEOF
    [ $? -eq 0 ] || die "$1: mutator failed"
    cmp -s "$T/$F" "$SEC/$F" && die "$1: file UNCHANGED after mutation"
    MD=$(diff "$SEC/$F" "$T/$F" | grep -c "^[<>]"); say "    [$1] mutant diff vs SEC: $MD lines; first added: $(diff "$SEC/$F" "$T/$F" | grep "^>" | head -1 | cut -c1-100)"; [ "$MD" -gt 0 ] || die "$1: MUTATION NOT APPLIED"
    build "$1"
    say "    [$1] binary $(date -r "$T/gxemul" +%H:%M:%S)  source $(date -r "$T/$F" +%H:%M:%S)"
    score "$1" "$2" "$OUT" ""
    [ "$4" = both ] && score "$1" "pass-3 instrument: 36/36 owed = the measured breach" "$OUT/old36" ".old36"
}
say "BASE -- 46/46 owed on the repaired instrument, 36/36 on the pass-3 one"; build BASE
score BASE CONTROL "$OUT" ""; score BASE "CONTROL, pass-3 instrument" "$OUT/old36" ".old36"
[ "$(grep -m1 PCC2D_RESULT "$OUT/BASE.out" | cut -d= -f2)" = "46/46" ] || die "BASE IS NOT FULL: $(grep -m1 PCC2D_RED "$OUT/BASE.out")"
[ "$(grep -m1 PCC2D_RESULT "$OUT/BASE.old36.out" | cut -d= -f2)" = "36/36" ] || die "the pass-3 instrument is NOT full on the repaired product: $(grep -m1 PCC2D_RED "$OUT/BASE.old36.out")"
